<script setup lang="ts">
import {computed,defineComponent,h,onBeforeUnmount,ref,watch} from 'vue'
import {onBeforeRouteLeave,onBeforeRouteUpdate,useRouter} from 'vue-router'
import {ElDrawer,ElMessage,ElMessageBox} from 'element-plus'
import {useUserStore} from '@/stores/user'
import {newRequestId} from '@/api/modules/partner'
import * as api from '@/api/modules/productMasterData'
import type {ProductMasterInput,ProductMasterRecord} from '@/api/modules/productMasterData'
import type {MasterDataLifecycleAction,MasterDataIdentity} from '@/types/masterDataLifecycle'
import MasterDataLifecycleDialog from '@/components/MasterDataLifecycleDialog.vue'
import PhoneModelMultiSelect from '@/components/PhoneModelMultiSelect/index.vue'
const props=defineProps<{modelValue:boolean;initialId?:number;create?:boolean;embedded?:boolean}>()
const emit=defineEmits<{'update:modelValue':[boolean];changed:[]}>()
// One body and one write path serve both the primary master list and exact-record drawers.
const MasterFrame=defineComponent({inheritAttrs:false,props:{embedded:Boolean,visible:Boolean},emits:['close'],setup(frame,{attrs,slots,emit}){return()=>frame.embedded?h('section',{...attrs,class:['product-master-inline',attrs.class]},[slots.default?.(),h('footer',{class:'master-inline-footer'},slots.footer?.())]):h(ElDrawer,{...attrs,modelValue:frame.visible,beforeClose:()=>emit('close')},slots)}})
const user=useUserStore(),router=useRouter(),editable=computed(()=>!!user.profile?.canMaintainEngineeringData||user.hasPermission('*'))
const rows=ref<ProductMasterRecord[]>([]),total=ref(0),page=ref(1),keyword=ref(''),loading=ref(false),error=ref(''),selected=ref<ProductMasterRecord>(),editing=ref(false),busy=ref(false),parents=ref<ProductMasterRecord[]>([]),parentKeyword=ref('')
const phones=ref<number[]>([]),lifecycle=ref<MasterDataIdentity>(),action=ref<MasterDataLifecycleAction>('delete')
const empty=():ProductMasterInput=>({productName:'',productType:'product_line',parentProductId:null,productCode:'',productSpecificCode:null,phoneModelId:null,model:null,material:null,remark:null,version:1,requestId:newRequestId(),reason:''})
const form=ref<ProductMasterInput>(empty()),loaded=ref(''),attemptSignature=ref('');let generation=0,parentGeneration=0
const dirty=computed(()=>editing.value&&JSON.stringify({...form.value,phoneModelId:phones.value[0]||null})!==loaded.value)
function initialize(row?:ProductMasterRecord,edit=true){selected.value=row;editing.value=edit;form.value=row?{productName:row.name,productType:row.productType,parentProductId:row.parentProductId??null,productCode:row.code,productSpecificCode:row.productSpecificCode??null,phoneModelId:row.phoneModelId??null,model:row.model??null,material:row.material??null,remark:row.remark??null,version:row.version,requestId:newRequestId(),reason:''}:empty();phones.value=row?.phoneModelId?[row.phoneModelId]:[];loaded.value=JSON.stringify(form.value);attemptSignature.value='';error.value=''}
async function mayReplace(){if(busy.value)return false;if(!dirty.value)return true;try{await ElMessageBox.confirm('尚有未保存内容，确定放弃？','未保存修改');return true}catch{return false}}
async function load(){const serial=++generation,token=user.token;loading.value=true;error.value='';try{const r=await api.getProductMasters(keyword.value,page.value);if(serial===generation&&token===user.token){rows.value=r.content;total.value=r.totalElements}}catch(e){if(serial===generation&&token===user.token)error.value=e instanceof Error?e.message:'资料读取失败'}finally{if(serial===generation&&token===user.token)loading.value=false}}
async function open(id:number,edit=false){if(!await mayReplace())return;const serial=++generation,token=user.token;loading.value=true;error.value='';try{const row=await api.getProductMaster(id);if(serial===generation&&token===user.token){if(edit&&row.editingPath){await router.push(row.editingPath);return}initialize(row,edit)}}catch(e){if(serial===generation&&token===user.token)error.value=e instanceof Error?e.message:'详情读取失败'}finally{if(serial===generation&&token===user.token)loading.value=false}}
function editSelected(){if(!selected.value)return;if(selected.value.editingPath)void router.push(selected.value.editingPath);else initialize(selected.value,true)}
async function create(){if(await mayReplace())initialize()}
async function backToList(){if(await mayReplace()){selected.value=undefined;editing.value=false;await load()}}
async function close(){if(await mayReplace()){++generation;emit('update:modelValue',false)}}
async function searchParents(search:string){parentKeyword.value=search;const serial=++parentGeneration,token=user.token;try{const r=await api.getProductMasters(search,1,50);if(serial===parentGeneration&&token===user.token)parents.value=r.content.filter(x=>x.productType==='product_line'&&x.status==='active')}catch(e){if(serial===parentGeneration&&token===user.token)error.value=e instanceof Error?e.message:'产品候选读取失败'}}
async function save(){if(!editable.value||busy.value)return;error.value='';if(!form.value.productName.trim()||!form.value.reason.trim()){error.value='请填写产品名称和维护原因';return}if(!selected.value&&form.value.productType==='model_variant'&&(!form.value.parentProductId||!phones.value.length)){error.value='请选择所属产品和标准手机';return}const input={...form.value,phoneModelId:phones.value[0]||null};const signature=JSON.stringify({...input,requestId:undefined});if(signature!==attemptSignature.value){input.requestId=newRequestId();form.value.requestId=input.requestId;attemptSignature.value=signature}const token=user.token;busy.value=true;try{const row=await api.saveProductMaster(selected.value?.id,input);if(token!==user.token)return;initialize(row,false);ElMessage.success('产品资料已保存');emit('changed');await load()}catch(e){if(token===user.token)error.value=e instanceof Error?e.message:'保存失败，请重试'}finally{if(token===user.token)busy.value=false}}
function maintain(row:ProductMasterRecord,value:MasterDataLifecycleAction){lifecycle.value={id:row.id,name:row.name,code:row.code};action.value=value}
async function completed(){lifecycle.value=undefined;emit('changed');selected.value=undefined;editing.value=false;await load()}
defineExpose({mayLeave:mayReplace})
onBeforeRouteLeave(()=>props.modelValue?mayReplace():true);onBeforeRouteUpdate(()=>props.modelValue?mayReplace():true)
onBeforeUnmount(()=>{++generation;++parentGeneration})
watch(()=>props.modelValue,async visible=>{++generation;selected.value=undefined;editing.value=false;error.value='';lifecycle.value=undefined;if(visible){await load();if(props.initialId)await open(props.initialId);else if(props.create)initialize();void searchParents('')}},{immediate:true})
watch(()=>user.token,()=>{++generation;++parentGeneration;rows.value=[];selected.value=undefined;lifecycle.value=undefined;editing.value=false;emit('update:modelValue',false)},{flush:'sync'})
</script>
<template>
<MasterFrame :embedded="embedded" :visible="modelValue" @close="close" title="产品平台与型号资料" size="min(1040px,96vw)" class="product-master-data-drawer"  :close-on-click-modal="false" :close-on-press-escape="false" append-to-body>
  <section class="product-master-data" :class="{'is-editing':selected||editing}" v-loading="loading"><h2 v-if="embedded">产品平台与型号</h2><header class="master-toolbar"><el-button v-if="selected||editing" size="small" :disabled="busy" @click="backToList">返回列表</el-button><el-input v-if="!selected&&!editing" v-model="keyword" clearable placeholder="名称／编码／型号" aria-label="查询产品资料" @keyup.enter="page=1;load()"/><el-button v-if="!selected&&!editing" size="small" @click="page=1;load()">查询</el-button><el-button v-if="editable" type="primary" size="small" :disabled="busy" @click="create">新增产品资料</el-button></header>
  <el-alert v-if="error" :title="error" type="error" :closable="false"/>
  <div v-if="selected||editing" class="master-editor"><header><strong>{{selected?selected.name:'新增产品资料'}}</strong><span v-if="selected">{{selected.code}} · {{selected.status==='active'?'在用':'已停用'}}</span><div v-if="selected&&editable" class="master-actions"><el-button v-if="!editing" size="small" @click="editSelected">编辑</el-button><el-button size="small" @click="maintain(selected,'delete')">引用／删除</el-button><el-button size="small" @click="maintain(selected,selected.status==='inactive'?'activate':'deactivate')">{{selected.status==='inactive'?'启用':'停用'}}</el-button></div></header>
    <el-form label-position="top" :disabled="busy||!editing||!editable"><el-form-item label="资料类型" required><span v-if="form.productType==='sku'">成品 SKU</span><el-radio-group v-else v-model="form.productType" :disabled="!!selected"><el-radio-button value="product_line">产品平台</el-radio-button><el-radio-button value="model_variant">产品型号</el-radio-button></el-radio-group></el-form-item><el-form-item label="产品名称" required><el-input v-model="form.productName" :disabled="!!selected?.sourceOwned" maxlength="255"/></el-form-item><el-form-item v-if="!selected" label="资料编码（未填自动分配唯一编号）"><el-input v-model="form.productCode" maxlength="64"/></el-form-item><el-form-item v-if="form.productType==='product_line'" label="产品特定编码（首次分配后保留）"><el-input v-model="form.productSpecificCode" :disabled="!!selected&&(!!selected.productSpecificCode||selected.sourceOwned)" maxlength="2"/></el-form-item><el-form-item v-if="form.productType==='model_variant'" label="所属产品" required><el-select v-model="form.parentProductId" :disabled="!!selected" filterable remote :remote-method="searchParents" placeholder="搜索已有产品"><el-option v-for="p in parents" :key="p.id" :label="`${p.name} · ${p.code}`" :value="p.id"/></el-select><span v-if="selected&&form.parentProductId" class="field-value">产品 #{{form.parentProductId}}</span></el-form-item><el-form-item v-if="form.productType==='model_variant'" label="标准手机" required><PhoneModelMultiSelect v-model="phones" :multiple="false" :disabled="!!selected||!editing" aria-label="产品型号对应手机"/></el-form-item><el-form-item label="型号说明"><el-input v-model="form.model" :disabled="!!selected?.sourceOwned||!!selected?.phoneModelId||phones.length>0" maxlength="128"/></el-form-item><el-form-item label="材料"><el-input v-model="form.material" maxlength="128"/></el-form-item><el-form-item label="备注"><el-input v-model="form.remark" type="textarea" :autosize="{minRows:2}" maxlength="2000"/></el-form-item><el-form-item v-if="editing" label="维护原因" required><el-input v-model="form.reason" type="textarea" :autosize="{minRows:2}" maxlength="2000"/></el-form-item></el-form><p v-if="selected?.sourceOwned" class="source-note">来源 {{selected.sourceSystem?.toUpperCase()}}：名称、编码、型号保持来源原值，本页维护本地材料和备注。</p><div v-if="editing&&editable" class="master-actions"><el-button :disabled="busy" @click="selected?initialize(selected,false):initialize(undefined,false)">取消编辑</el-button><el-button type="primary" :loading="busy" @click="save">保存资料</el-button></div>
  </div>
  <div v-if="!selected&&!editing" class="master-records"><article v-for="row in rows" :key="row.id"><div><button class="record-link" @click="open(row.id)">{{row.name}}</button><small>{{row.code}} · {{row.productType==='product_line'?'产品平台':'型号'}}<template v-if="row.model"> · {{row.model}}</template></small></div><el-tag size="small" :type="row.status==='inactive'?'info':'success'">{{row.status==='inactive'?'已停用':'在用'}}</el-tag><div class="master-actions"><el-button size="small" link @click="open(row.id)">查看</el-button><template v-if="editable"><el-button size="small" link @click="open(row.id,true)">编辑</el-button><el-button size="small" link @click="maintain(row,row.status==='inactive'?'activate':'deactivate')">{{row.status==='inactive'?'启用':'停用'}}</el-button><el-button size="small" link type="danger" @click="maintain(row,'delete')">删除</el-button></template></div></article><el-empty v-if="!rows.length&&!loading" description="没有匹配的产品资料"/></div>
  </section><template #footer><el-pagination v-if="!selected&&!editing" v-model:current-page="page" :page-size="50" :total="total" layout="total,prev,pager,next" @current-change="load"/><el-button v-if="!embedded" :disabled="busy" @click="close">关闭</el-button></template>
</MasterFrame>
<MasterDataLifecycleDialog :record="lifecycle" kind-label="产品资料" :action="action" :editable="editable" :context="user.token" :load="api.inspectProductMaster" :perform="api.actOnProductMaster" @close="lifecycle=undefined" @completed="completed" @open="path=>router.push(path)"/>
</template>
<style scoped>
.product-master-data{height:100%;min-height:0;min-width:0;display:flex;flex-direction:column;gap:8px;font-size:12px;overflow:hidden}.product-master-data h2{font-size:16px;font-weight:700;color:#183e63;line-height:28px;margin:0}.product-master-data.is-editing{overflow:auto}.product-master-data.is-editing .master-records{flex:none;overflow:visible}.product-master-inline{height:100%;min-height:0;display:flex;flex-direction:column;gap:8px;min-width:0}.product-master-inline>.product-master-data{flex:1;height:auto}.master-inline-footer{display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap;flex:none}.master-toolbar,.master-actions,.master-editor>header{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.master-toolbar{flex:none}.master-toolbar>.el-input{flex:1;min-width:140px}.master-editor{flex:none;box-sizing:border-box;max-width:1100px;width:100%;border:1px solid #c7d6e8;background:#fff;padding:14px}.master-editor>header{margin-bottom:12px}.master-editor strong{font-size:16px;color:#173958}.master-editor>header span,.field-value{color:#61758c}.master-editor :deep(.el-form-item__label){font-size:12px;font-weight:600;color:#294f75}.master-editor :deep(.el-form-item){margin-bottom:12px}.master-editor :deep(.el-input__wrapper),.master-editor :deep(.el-textarea__inner){font-size:12px;background:#f9fbff}.master-editor :deep(.el-select){width:100%}.master-records{flex:1;min-height:100px;overflow:auto}.master-records article{display:flex;align-items:center;gap:10px;padding:8px;border-bottom:1px solid #e1e8f0;flex-wrap:wrap}.master-records article>div:first-child{flex:1;min-width:180px;overflow-wrap:anywhere}.master-records small{display:block;color:#6d7f93;margin-top:3px}.record-link{border:0;background:none;padding:0;color:#245e9c;text-align:left;font:inherit;font-weight:600;cursor:pointer;overflow-wrap:anywhere}.source-note{color:#61758c;line-height:1.5}.master-editor :deep(.el-input.is-disabled .el-input__inner){-webkit-text-fill-color:#334b66;color:#334b66}.master-editor :deep(.el-textarea.is-disabled .el-textarea__inner){color:#334b66}:deep(.el-pagination){flex-wrap:wrap}
</style>
